mapper.update:
UPDATE health_report
SET workspace_task_id = #{workspaceTaskId},
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE health_report
SET is_deleted = 1,
    gmt_deleted = #{gmtDeleted},
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND is_deleted = 0

mapper.select:
SELECT 
FROM health_report
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND period_type = #{periodType}
  AND period_start = #{periodStart}
  AND is_deleted = 0
LIMIT 1

SELECT 
FROM health_report
WHERE people_id = #{peopleId}
  AND is_deleted = 0

  AND status = #{status}

ORDER BY period_start DESC, gmt_created DESC
LIMIT #{limit}

SELECT people_id
FROM people_care_assignment
WHERE tenant_id = #{tenantId}
  AND primary_org_id = #{orgId}
  AND is_deleted = 0
ORDER BY gmt_modified DESC
LIMIT #{limit}
